import React from 'react';
import { graphql } from 'gatsby';
import { Link } from "gatsby"
import Layout from '../components/layout';
import SeO from '../components/seo'


const PostTemplate = ({ data }) => {
  const { markdownRemark } = data;
  const { frontmatter, html, excerpt, rawMarkdownBody } = markdownRemark;

return (
    <Layout>
      <section style={{margin:0.5+`em`,overflow:`hidden`}}>
       <ul className="breadcrumb">
        <li><Link to="/">Home</Link></li>
       <li><Link to="/blog">Blog</Link></li>
        <li>{frontmatter.title}</li>
        </ul>
      <div>
      <h1>{frontmatter.title}</h1>
          <em>{frontmatter.displayDate}</em>
        </div>
        <div dangerouslySetInnerHTML={{ __html: html }} />
      </section>
    </Layout>
  );
};

export function Head({ data, location }) {
    const markdownRemark = data.markdownRemark;
  const { frontmatter, excerpt, rawMarkdownBody } = markdownRemark;
    const siteUrl = data.site.siteMetadata.url;
    const url = siteUrl + markdownRemark.fields.slug;

    let img = null;
    let imgW = 0;
    let imgH = 0;
   
    const imageData = frontmatter.icon?.childImageSharp?.gatsbyImageData

    if ( imageData ) {
        img=imageData?.images?.fallback?.src
        imgW=imageData?.width
        imgH=imageData?.height
    }

  const tags = (frontmatter.tags) ? frontmatter.tags : "Post Writing Poet";
  const schema = {
        "@context": "https://schema.org",
        "@type": "Article",
        "@id": url,
        "name": frontmatter.title,
        "url": url,
        "description": excerpt,
        "headline": frontmatter.title,
        "datePublished": frontmatter.date,
        "inLanguage": "en-GB",
        "articleBody": rawMarkdownBody,
        "keywords": tags.split(/[\s,]+/).filter(Boolean),
        "author": {
            "@type": "Person",
            "name": "Christian Lacdael",
            "url": `${siteUrl}/christian-lacdael`,
        },
        "publisher": {
            "@type": "Organization",
            "name": "Poetry.me",
            "url": siteUrl,
        },
        "mainEntityOfPage": { "@id": url },
    };

   if (img) schema["image"] = {"@type":"ImageObject","url":(`${siteUrl}${img}`),"width":imgW,"height":imgH};
 
  
  return (
    <SeO
	title={ frontmatter.title }
	 description={excerpt} tags={tags}
	  date={ frontmatter.date }
	  image={img}
	  imageAlt={frontmatter.title}
	  what="article"
	  schemaMarkup={ schema } />
  );
}


export default PostTemplate;



export const pageQuery = graphql`
  query($slug: String!) {
  	site {
        siteMetadata {
            url
        }
    }
    markdownRemark(fields: { slug: { eq: $slug } }) {
      html
      excerpt(pruneLength: 250)
      rawMarkdownBody
      fields{
        slug
      }
      frontmatter {
        date
        displayDate: date(formatString: "MMMM DD, YYYY")
        title
        tags
        icon {
    	    childImageSharp {
      	        gatsbyImageData(width: 1200)
    	    }
    	}
     }
  }
}`;
